# Build the attribution and source-hash manifest after preparing the decks.
import pathlib,sys,json,hashlib,gzip
D=pathlib.Path(sys.argv[1]).resolve();S=pathlib.Path(__file__).resolve().parent.parent/'src'
records=[
('frequency.txt','https://raw.githubusercontent.com/hermitdave/FrequencyWords/master/content/2018/it/it_full.txt','Italian subtitle word-form occurrence counts','Hermit Dave and FrequencyWords contributors; OPUS/OpenSubtitles2018','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/'),
('englishFrequency.txt','https://raw.githubusercontent.com/hermitdave/FrequencyWords/master/content/2018/en/en_50k.txt','English glossary selection heuristic','Hermit Dave and FrequencyWords contributors; OPUS/OpenSubtitles2018','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/'),
('morphit.txt','https://raw.githubusercontent.com/TraMOOC-Impleval/lemmatize_italian_data/master/morph-it_048_utf8.txt','Morph-it! 0.4.8 form-to-lemma analysis','Marco Baroni and Eros Zanchetta, 2004-2009','Dual-licensed CC BY-SA 2.0 / LGPL; CC BY-SA 2.0 route used','https://creativecommons.org/licenses/by-sa/2.0/'),
('wikdict.tei','https://download.wikdict.com/dictionaries/tei/recommended/ita-eng.tei','Supplemental translation candidates, accepted only when attested in an English Wiktionary definition','Wiktionary contributors; DBnary; WikDict / Karl Bartel, edition 2025.11.21','CC BY-SA 3.0','https://creativecommons.org/licenses/by-sa/3.0/'),
('kaikki-Italian.jsonl.gz','https://kaikki.org/dictionary/Italian/kaikki.org-dictionary-Italian.jsonl','English Wiktionary Italian headword definitions; dump 2026-09-02, extraction 2026-10-03; local input gzip-compressed without content changes','English Wiktionary contributors; extraction Tatu Ylonen / Wiktextract / Kaikki.org','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/'),
('sentences.csv','https://raw.githubusercontent.com/orgtre/top-open-subtitles-sentences/main/bld/top_sentences/it_top_sentences.csv','Sentence occurrence counts, not sentence translations','orgtre and contributors; underlying OPUS/OpenSubtitles2018 corpus','Underlying corpus terms; counts are ranking metadata','https://github.com/orgtre/top-open-subtitles-sentences#license'),
('tatoeba.zip','https://raw.githubusercontent.com/rishabhrao1997/Italian-to-English-Translation-Using-Attention-Mechanism/master/ita-eng.zip','Unchanged mirror of ManyThings/Tatoeba Italian-English pairs, file dated 2020-08-23','Tatoeba contributors; selected by CK at ManyThings.org; exact IDs and authors in italian-sentence-sources.json','CC BY 2.0 France as marked in individual attribution records','https://creativecommons.org/licenses/by/2.0/fr/')]
a=[]
for f,url,purpose,author,lic,licurl in records:
 b=(D/f).read_bytes();r={'filename':f,'url':url,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'purpose':purpose,'attribution':author,'license':lic,'license_url':licurl}
 if f.endswith('.gz'):
  h=hashlib.sha256();n=0
  with gzip.open(D/f,'rb') as z:
   while chunk:=z.read(1048576):h.update(chunk);n+=len(chunk)
  r['upstream_uncompressed_sha256']=h.hexdigest();r['upstream_uncompressed_bytes']=n
 a.append(r)
words=json.loads((S/'italian-words.json').read_text(encoding='utf8'));sent=json.loads((S/'italian-sentences.json').read_text(encoding='utf8'))
out={'retrieved':'2026-10-16','language':'Italian','word_count':len(words),'sentence_count':len(sent),'word_schema':['Italian headword','simple English meaning','part of speech','estimated subtitle lemma frequency'],'sentence_schema':['Italian sentence','English translation','subtitle occurrence count','original corpus rank'],'word_ranking':'Morph-it lemma frequencies estimated from subtitle word forms; ambiguous forms split in proportion to square root of each candidate lemma surface frequency. Descending estimates after lexical quality filters. This is not a universal ranking.','sentence_ranking':'First 1000 unique short, everyday, directly Tatoeba-paired Italian sentences surviving the filters, ordered by descending OpenSubtitles2018 occurrence count.','word_attribution_url_template':'https://en.wiktionary.org/wiki/{URL-encoded Italian headword}#Italian','word_authors_history_template':'https://en.wiktionary.org/w/index.php?title={URL-encoded Italian headword}&action=history','attribution_file':'italian-sentence-sources.json','sentence_attributions':json.loads((S/'italian-sentence-sources.json').read_text(encoding='utf8')),'changes':'Selected, deduplicated, lemmatized, filtered and simplified. Editorial word and sentence corrections are preserved in the override TSV files. Adapted dictionary text retains CC BY-SA 4.0; Morph-it-derived lemma analysis retains CC BY-SA 2.0; Tatoeba sentence pairs retain their marked CC BY 2.0 France terms. Components retain their own license notices.','quality_limit':'Every displayed pair was editorially reviewed; no native-speaker certification or universal frequency claim. One short gloss cannot show all meanings of a word.','sources':a}
(S/'italian-sources.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf8')
print('Source manifest saved; 7 input files hashed.')
